// Command gen extracts `// godex-feature:` comment blocks from the Go source
// tree and emits internal/selfdocs/features_gen.go.
//
// Usage (from the repo root):
//
//	go generate ./internal/selfdocs/...
//	# or
//	go run ./internal/selfdocs/gen
//
// The generated file is checked in so the binary always carries the knowledge
// base; re-run after editing any marker comment.
package main

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"github.com/tim5wang/godex/internal/selfdocs"
)

const markerPrefix = "godex-feature:"

type feature struct {
	id       string
	title    string
	desc     []string
	entries  []string
	docs     []string
	location string
}

func main() {
	root, err := repoRoot()
	if err != nil {
		fatal(err)
	}
	features, err := scanTree(root)
	if err != nil {
		fatal(err)
	}
	out := filepath.Join(root, "internal", "selfdocs", "features_gen.go")
	if err := writeGen(out, features); err != nil {
		fatal(err)
	}
	fmt.Printf("selfdocs: wrote %d features to %s\n", len(features), filepath.ToSlash(out))
}

func repoRoot() (string, error) {
	dir, err := os.Getwd()
	if err != nil {
		return "", err
	}
	for {
		if _, err := os.Stat(filepath.Join(dir, "go.mod")); err == nil {
			return dir, nil
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return "", fmt.Errorf("go.mod not found above %s", dir)
		}
		dir = parent
	}
}

func scanTree(root string) ([]feature, error) {
	var files []string
	for _, dir := range []string{"internal", "cmd"} {
		err := filepath.WalkDir(filepath.Join(root, dir), func(path string, d os.DirEntry, err error) error {
			if err != nil {
				return err
			}
			if d.IsDir() {
				return nil
			}
			if strings.HasSuffix(path, ".go") && !strings.HasSuffix(path, "_test.go") {
				files = append(files, path)
			}
			return nil
		})
		if err != nil {
			return nil, err
		}
	}
	sort.Strings(files)

	fset := token.NewFileSet()
	var out []feature
	seen := map[string]string{} // id -> location for dup detection
	for _, path := range files {
		f, err := parser.ParseFile(fset, path, nil, parser.ParseComments)
		if err != nil {
			return nil, fmt.Errorf("parse %s: %w", path, err)
		}
		for _, cg := range f.Comments {
			fc, ok := parseCommentGroup(cg)
			if !ok {
				continue
			}
			pos := fset.Position(cg.Pos())
			rel, relErr := filepath.Rel(root, path)
			locPath := filepath.ToSlash(path)
			if relErr == nil {
				locPath = filepath.ToSlash(rel)
			}
			fc.location = fmt.Sprintf("%s:%d", locPath, pos.Line)
			if prev, dup := seen[fc.id]; dup {
				return nil, fmt.Errorf("duplicate godex-feature id %q at %s (first at %s)", fc.id, fc.location, prev)
			}
			seen[fc.id] = fc.location
			out = append(out, fc)
		}
	}
	sort.Slice(out, func(i, j int) bool { return out[i].id < out[j].id })
	return out, nil
}

// parseCommentGroup recognizes a `// godex-feature:` block. The marker may be
// any line in the comment group (so a feature block can sit after an existing
// package doc comment); following lines up to the group end are the
// description.
func parseCommentGroup(cg *ast.CommentGroup) (feature, bool) {
	text := cg.Text() // strips // and /* */, normalizes indentation
	lines := strings.Split(text, "\n")
	markerIdx := -1
	for i, l := range lines {
		if strings.HasPrefix(strings.TrimSpace(l), markerPrefix) {
			markerIdx = i
			break
		}
	}
	if markerIdx < 0 {
		return feature{}, false
	}
	first := strings.TrimSpace(lines[markerIdx])
	id := strings.TrimSpace(strings.TrimPrefix(first, markerPrefix))
	if id == "" {
		return feature{}, false
	}

	f := feature{id: id}
	for _, raw := range lines[markerIdx+1:] {
		line := strings.TrimSpace(raw)
		if line == "" {
			continue
		}
		switch {
		case strings.HasPrefix(line, "标题："):
			f.title = strings.TrimSpace(strings.TrimPrefix(line, "标题："))
		case strings.HasPrefix(line, "入口："):
			f.entries = splitList(line, "入口：")
		case strings.HasPrefix(line, "文档："):
			f.docs = splitList(line, "文档：")
		default:
			f.desc = append(f.desc, line)
		}
	}
	return f, true
}

func splitList(line, prefix string) []string {
	rest := strings.TrimSpace(strings.TrimPrefix(line, prefix))
	if rest == "" {
		return nil
	}
	// Accept both comma and Chinese enumeration comma (、) as separators.
	parts := strings.FieldsFunc(rest, func(r rune) bool { return r == ',' || r == '、' })
	var out []string
	for _, p := range parts {
		if p = strings.TrimSpace(p); p != "" {
			out = append(out, p)
		}
	}
	return out
}

func writeGen(out string, features []feature) error {
	var b strings.Builder
	b.WriteString("// Code generated by go generate ./internal/selfdocs; DO NOT EDIT.\n")
	b.WriteString("// Source: `// godex-feature:` comment blocks in internal/ and cmd/.\n\n")
	b.WriteString("package selfdocs\n\n")
	b.WriteString("var generatedFeatures = []Feature{\n")
	for _, f := range features {
		fmt.Fprintf(&b, "\t{ID: %q, Title: %q, Description: %q, EntryPoints: %#v, Docs: %#v, Location: %q},\n",
			f.id, f.title, strings.Join(f.desc, "\n"), f.entries, f.docs, f.location)
	}
	b.WriteString("}\n")

	if err := os.MkdirAll(filepath.Dir(out), 0o755); err != nil {
		return err
	}
	return os.WriteFile(out, []byte(b.String()), 0o644)
}

func fatal(err error) {
	fmt.Fprintf(os.Stderr, "selfdocs gen: %v\n", err)
	os.Exit(1)
}

var _ = selfdocs.Feature{} // keep import linked for docs
